import { html, raw, extLink, type Html } from '../lib/html.ts';
import { brandIconPaths, uiIconPaths } from '../lib/icons.ts';
import { person } from '../content/person.ts';

export type Section = 'home' | 'academic' | 'blog' | 'none';

export const NAV: { section: Section; label: string; href: string }[] = [
  { section: 'home', label: 'Home', href: 'index.html' },
  { section: 'academic', label: 'Academic', href: 'academic.html' },
  { section: 'blog', label: 'Blog', href: 'blog.html' },
];

export const GENERATED_NOTICE =
  '<!-- Generated by src/build.ts. Edit the content in src/content/ and run `npm run build`; do not edit this file by hand. -->';

// ---------------------------------------------------------------------------
// Icons
// ---------------------------------------------------------------------------

export function brandIcon(id: string, size = 18): Html {
  const d = brandIconPaths[id];
  if (!d) return html``;
  return html`<svg class="icon icon--brand" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="${d}"/></svg>`;
}

export function uiIcon(id: keyof typeof uiIconPaths | string, size = 18): Html {
  const d = uiIconPaths[id];
  return html`<svg class="icon icon--ui" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" d="${d}"/></svg>`;
}

// ---------------------------------------------------------------------------
// Header & footer — shared with the hand-written posts and notes, which get a
// copy through `syncChrome` in build.ts. `root` is the relative path back to
// the site root ('' for root pages, '../' for posts, '../../' for notes).
// ---------------------------------------------------------------------------

export function siteHeader(root: string, current: Section, sub?: Html): Html {
  // On the section's own page the link is the current page; on pages inside
  // the section (a post, a note) it marks the current section instead.
  const isLanding = sub === undefined;
  const items = NAV.map((item) => {
    const aria = item.section === current ? html` aria-current="${isLanding ? 'page' : 'true'}"` : '';
    return html`<li><a href="${root}${item.href}"${aria}>${item.label}</a></li>`;
  });
  return html`<header class="site-header">
  <a class="skip-link" href="#main">Skip to content</a>
  <div class="site-header__inner wrap">
    <a class="brand" href="${root}index.html" aria-label="Diogo Sousa Franquinho, home"><span class="brand__given">Diogo</span><span class="brand__initial" aria-hidden="true">D.</span> <span class="brand__middle">Sousa </span><span class="brand__family">Franquinho</span></a>
    <nav class="site-nav" aria-label="Main">
      <ul>
        ${items}
      </ul>
    </nav>
  </div>${sub ?? ''}
</header>`;
}

export function siteFooter(root: string): Html {
  const visible = person.profiles.filter((p) => !p.hidden);
  return html`<footer class="site-footer">
  <div class="wrap site-footer__grid">
    <div class="site-footer__id">
      <p class="site-footer__name">${person.name}</p>
      <p>${person.role}<br>${person.institutionsLine}</p>
    </div>
    <nav class="site-footer__col" aria-label="Footer">
      <p class="footer-label">Site</p>
      <ul>
        ${NAV.map((n) => html`<li><a href="${root}${n.href}">${n.label}</a></li>`)}
        <li><a href="${root}book_reviews/list.html">Reading list</a></li>
      </ul>
    </nav>
    <div class="site-footer__col">
      <p class="footer-label">Elsewhere</p>
      <ul>
        ${visible.map((p) => html`<li>${extLink(p.url, p.label, { arrow: false })}</li>`)}
      </ul>
    </div>
  </div>
  <div class="wrap site-footer__base">
    <p>© ${person.name}</p>
    <p><a href="mailto:${person.emails[0].address}">${person.emails[0].address}</a></p>
  </div>
</footer>`;
}

// ---------------------------------------------------------------------------
// Document shell for generated pages
// ---------------------------------------------------------------------------

export interface PageOptions {
  /** Output path relative to the site root, e.g. 'academic.html'. */
  path: string;
  title: string;
  description: string;
  section: Section;
  ogType?: 'website' | 'profile' | 'article';
  ogImage?: string;
  ogImageAlt?: string;
  jsonLd?: object[];
  bodyClass?: string;
  /** Extra deferred scripts, relative to the site root. */
  scripts?: string[];
  /** Extra <head> markup (e.g. image preloads). */
  head?: Html;
  noindex?: boolean;
  /** Canonical URL override (used by redirect stubs). */
  canonical?: string;
  cssVersion: string;
  /** Prefix for site-relative URLs: '' for root pages, '/' for the 404 page. */
  root?: string;
}

export function canonicalUrl(path: string): string {
  return path === 'index.html' ? person.siteUrl : person.siteUrl + path;
}

export function page(opts: PageOptions, main: Html): Html {
  const canonical = opts.canonical ?? canonicalUrl(opts.path);
  const ogImage = person.siteUrl + (opts.ogImage ?? 'images/og/default.jpg');
  const r = opts.root ?? '';
  const scripts = ['js/site.js', ...(opts.scripts ?? [])];
  const jsonLd = (opts.jsonLd ?? []).map(
    // JSON is escaped for safe embedding in a <script> element.
    (obj) => raw(`<script type="application/ld+json">${JSON.stringify(obj).replace(/</g, '\\u003c')}</script>`),
  );
  return html`<!DOCTYPE html>
${raw(GENERATED_NOTICE)}
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${opts.title}</title>
  <meta name="description" content="${opts.description}">
  <meta name="author" content="${person.name}">
  ${opts.noindex ? html`<meta name="robots" content="noindex">` : ''}
  <link rel="canonical" href="${canonical}">
  <meta name="theme-color" content="#faf8f4">
  <meta property="og:site_name" content="${person.name}">
  <meta property="og:type" content="${opts.ogType ?? 'website'}">
  <meta property="og:title" content="${opts.title}">
  <meta property="og:description" content="${opts.description}">
  <meta property="og:url" content="${canonical}">
  <meta property="og:image" content="${ogImage}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:image:alt" content="${opts.ogImageAlt ?? `${person.name} — ${person.role}`}">
  <meta property="og:locale" content="en_GB">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="${opts.title}">
  <meta name="twitter:description" content="${opts.description}">
  <meta name="twitter:image" content="${ogImage}">
  <link rel="icon" href="${r}images/favicon.ico" sizes="any">
  <link rel="icon" type="image/png" sizes="32x32" href="${r}images/favicon-32x32.png">
  <link rel="icon" type="image/png" sizes="16x16" href="${r}images/favicon-16x16.png">
  <link rel="apple-touch-icon" sizes="180x180" href="${r}images/apple-touch-icon.png">
  <link rel="preload" href="${r}fonts/inter-roman-latin.woff2" as="font" type="font/woff2" crossorigin>
  <link rel="preload" href="${r}fonts/newsreader-roman-latin.woff2" as="font" type="font/woff2" crossorigin>
  ${opts.head ?? ''}
  <link rel="stylesheet" href="${r}css/style.css?v=${opts.cssVersion}">
  <script src="${r}js/analytics-config.js"></script>
  <script src="${r}js/analytics.js" defer></script>
  ${scripts.map((s) => html`<script src="${r}${s}" defer></script>`)}
  ${jsonLd}
</head>
<body class="${opts.bodyClass ?? ''}">
${siteHeader(r, opts.section)}
<main id="main" class="site-main" tabindex="-1">
${main}
</main>
${siteFooter(r)}
</body>
</html>
`;
}
